import { useState } from 'react';
import { MapPin, Phone, Mail, Github, Instagram, Send, Linkedin } from 'lucide-react';

const ContactFooter = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: ''
  });
  const [submissionState, setSubmissionState] = useState({
    submitting: false,
    success: false,
    error: false
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmissionState({ submitting: true, success: false, error: false });

    try {
      const response = await fetch("https://formspree.io/f/movvaney", {
        method: "POST",
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          name: formData.name,
          email: formData.email,
          phone: formData.phone,
          message: formData.message
        }),
      });

      if (response.ok) {
        setSubmissionState({ submitting: false, success: true, error: false });
        setFormData({
          name: '',
          email: '',
          phone: '',
          message: ''
        });
      } else {
        throw new Error('Form submission failed');
      }
    } catch (error) {
      setSubmissionState({ submitting: false, success: false, error: true });
    }
  };

  // Updated social links to match the Hero section
  const socialLinks = [
    {
      icon: <Github size={18} />,
      label: "GitHub",
      url: "https://github.com/AnimeshKumarRai",
    },
    {
      icon: <Instagram size={18} />,
      label: "Instagram",
      url: "https://instagram.com/animesh__rai",
    },
    {
      icon: <Send size={18} />, // Telegram icon (using Send from lucide-react)
      label: "Telegram",
      url: "https://t.me/animeshrai",
    },
    {
      icon: <Linkedin size={18} />,
      label: "LinkedIn",
      url: "https://linkedin.com/in/animeshkrrai",
    },
  ];

  return (
    <>
      {/* Contact Section */}
      <section id="contact" className="py-20 dark:bg-gray-900 bg-gray-100 mb-20 mt-32">
        <div className="container mx-auto px-4">
          <div className="grid md:grid-cols-2 gap-8">
            <div className="relative pl-0 md:pl-10">
              <p className="top-0 left-0 md:-left-10 md:top-0 md:transform md:-rotate-90 md:origin-left-top md:-translate-x-full text-gray-500 dark:text-gray-400 uppercase tracking-wider text-sm pb-1 mb-5 md:mb-0 relative after:content-[''] after:absolute after:top-full after:left-0 md:after:left-auto md:after:right-[calc(100%+20px)] after:w-14 after:h-0.5 after:bg-gray-500 dark:after:bg-gray-400">
                Contact
              </p>

              <h2 className="text-3xl font-poppins mb-6 dark:text-white text-gray-900">
                Have you any project? Drop a message!
              </h2>

              <p className="text-gray-600 dark:text-gray-300 leading-relaxed mb-8">
                Get in touch and let me know if I can help! Fill out the form and I'll be in touch as soon as possible
              </p>

              <ul className="space-y-6 ml-0 md:ml-10">
                <li className="flex items-start gap-4">
                  <div className="text-2xl text-gray-900 dark:text-white mt-1">
                    <MapPin size={24} />
                  </div>
                  <div>
                    <h3 className="text-lg font-poppins dark:text-white text-gray-900 mb-2">Address:</h3>
                    <address className="text-gray-600 dark:text-gray-300 not-italic">
                      Varanasi, India
                    </address>
                  </div>
                </li>

                <li className="flex items-start gap-4">
                  <div className="text-2xl text-gray-900 dark:text-white mt-1">
                    <Mail size={24} />
                  </div>
                  <div>
                    <h3 className="text-lg font-poppins dark:text-white text-gray-900 mb-2">Email:</h3>
                    <div className="space-y-1">
                      <a href="mailto:animeshkomail@gmail.com" className="block text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors">
                        animeshkomail@gmail.com
                      </a>
                    </div>
                  </div>
                </li>

                <li className="ml-0 md:ml-10">
                  <ul className="flex flex-wrap gap-4 mt-10">
                    {socialLinks.map((social, index) => (
                      <li key={index}>
                        <a 
                          href={social.url} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="relative group w-9 h-9 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-full flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-colors"
                        >
                          {social.icon}
                          <span className="absolute -top-10 left-1/2 transform -translate-x-1/2 bg-emerald-500 text-white text-xs font-bold px-2 py-1 rounded opacity-0 group-hover:opacity-100 group-hover:-translate-y-1 transition-all duration-300 whitespace-nowrap">
                            {social.label}
                          </span>
                        </a>
                      </li>
                    ))}
                  </ul>
                </li>
              </ul>
            </div>

            <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-md">
              {submissionState.success ? (
                <div className="text-center py-8">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-emerald-500 mx-auto mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  <h3 className="text-2xl font-bold dark:text-white text-gray-900 mb-2">Thank you!</h3>
                  <p className="text-gray-600 dark:text-gray-300">Your message has been sent successfully.</p>
                  <button
                    onClick={() => setSubmissionState({ submitting: false, success: false, error: false })}
                    className="mt-6 bg-emerald-500 text-white font-bold uppercase tracking-wider py-2 px-6 rounded hover:bg-emerald-600 transition-colors"
                  >
                    Send another message
                  </button>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-6">
                  <div>
                    <label htmlFor="name" className="block text-sm font-poppins dark:text-white text-gray-900 mb-2 ml-1">
                      Name
                    </label>
                    <div className="relative">
                      <input
                        type="text"
                        id="name"
                        name="name"
                        value={formData.name}
                        onChange={handleChange}
                        required
                        placeholder="Your Name"
                        className="w-full bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white px-4 py-3 pl-10 rounded-xl border-none focus:outline focus:outline-1 focus:outline-gray-500"
                      />
                      <div className="absolute left-3 top-3 text-gray-500 dark:text-gray-400">
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
                          <circle cx="12" cy="7" r="4"></circle>
                        </svg>
                      </div>
                    </div>
                  </div>

                  <div>
                    <label htmlFor="email" className="block text-sm font-poppins dark:text-white text-gray-900 mb-2 ml-1">
                      Email
                    </label>
                    <div className="relative">
                      <input
                        type="email"
                        id="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        required
                        placeholder="name@mail.com"
                        className="w-full bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white px-4 py-3 pl-10 rounded-xl border-none focus:outline focus:outline-1 focus:outline-gray-500"
                      />
                      <div className="absolute left-3 top-3 text-gray-500 dark:text-gray-400">
                        <Mail size={20} />
                      </div>
                    </div>
                  </div>

                  <div>
                    <label htmlFor="phone" className="block text-sm font-poppins dark:text-white text-gray-900 mb-2 ml-1">
                      Phone
                    </label>
                    <div className="relative">
                      <input
                        type="tel"
                        id="phone"
                        name="phone"
                        value={formData.phone}
                        onChange={handleChange}
                        required
                        placeholder="Phone Number"
                        className="w-full bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white px-4 py-3 pl-10 rounded-xl border-none focus:outline focus:outline-1 focus:outline-gray-500"
                      />
                      <div className="absolute left-3 top-3 text-gray-500 dark:text-gray-400">
                        <Phone size={20} />
                      </div>
                    </div>
                  </div>

                  <div>
                    <label htmlFor="message" className="block text-sm font-poppins dark:text-white text-gray-900 mb-2 ml-1">
                      Message
                    </label>
                    <div className="relative">
                      <textarea
                        id="message"
                        name="message"
                        value={formData.message}
                        onChange={handleChange}
                        required
                        placeholder="Write your Message"
                        className="w-full bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white px-4 py-3 pl-10 rounded-xl border-none focus:outline focus:outline-1 focus:outline-gray-500 min-h-[120px] max-h-[200px]"
                      ></textarea>
                      <div className="absolute left-3 top-3 text-gray-500 dark:text-gray-400">
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path>
                        </svg>
                      </div>
                    </div>
                  </div>

                  {submissionState.error && (
                    <div className="text-red-500 text-sm">
                      There was an error submitting your message. Please try again.
                    </div>
                  )}

                  <button
                    type="submit"
                    disabled={submissionState.submitting}
                    className={`w-full bg-gray-900 dark:bg-white text-white dark:text-gray-900 font-bold uppercase tracking-wider py-3 px-6 rounded border border-gray-900 dark:border-white hover:bg-gray-700 dark:hover:bg-gray-200 transition-colors ${submissionState.submitting ? 'opacity-70 cursor-not-allowed' : ''}`}
                  >
                    {submissionState.submitting ? 'Sending...' : 'Send'}
                  </button>
                </form>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* Footer Section */}
      <footer className="bg-white dark:bg-gray-800 py-6 shadow-md">
        <div className="container mx-auto px-4">
          <div className="flex flex-col md:flex-row justify-between items-center">
            <h1 className="text-2xl font-saira-stencil dark:text-white text-gray-900 mb-4 md:mb-0">
              <a href="#home" className="flex items-center">
                Animesh<span className="text-emerald-500">.</span>Rai
              </a>
            </h1>

            <p className="text-gray-600 dark:text-gray-300 text-center md:text-right">
              &copy; 2025 Animesh Kumar Rai. All rights reserved
            </p>
          </div>
        </div>
      </footer>
    </>
  );
};

export default ContactFooter;