import { useEffect, useState } from 'react';
import Logo_White from "../assets/logo_white.svg";

const Loader = ({ onLoadingComplete }) => {
  const [scale, setScale] = useState(1);
  const [opacity, setOpacity] = useState(1);
  const [isVisible, setIsVisible] = useState(true);

  useEffect(() => {
    // Pulsing animation
    const pulseInterval = setInterval(() => {
      setScale(prev => prev === 1 ? 1.1 : 1);
    }, 800);

    // Zoom out and fade after 3 seconds
    const loadingTimeout = setTimeout(() => {
      clearInterval(pulseInterval);
      setScale(20);
      setOpacity(0);
      
      setTimeout(() => {
        setIsVisible(false);
        onLoadingComplete();
      }, 1000);
    }, 2000);

    return () => {
      clearInterval(pulseInterval);
      clearTimeout(loadingTimeout);
    };
  }, [onLoadingComplete]);

  if (!isVisible) return null;

  return (
    <div className="fixed inset-0 bg-gray-900 z-50 flex items-center justify-center transition-all duration-1000 ease-out"
         style={{ opacity }}>
      <img 
        src={Logo_White} 
        alt="Loading..." 
        className="w-32 h-32 transition-transform duration-1000 ease-out"
        style={{ transform: `scale(${scale})` }}
      />
    </div>
  );
};

export default Loader;