import { useState, useEffect, useRef } from "react";
import styled from "styled-components";
import thetraveldelight from "../assets/project-image/thetraveldelight.png";
import tutorkendra from "../assets/project-image/tutorkendra.png";
import phishingdetector from "../assets/project-image/phishing-detector.png"
import aiChat from "../assets/project-image/ai_chat_web_app.png"
import recipesApp from "../assets/project-image/recipes_android_app.png"
import weatherMap from "../assets/project-image/weather_map_websit.png"
import model3d from "../assets/project-image//3D_geological_model_.png"
import gestureMouse from "../assets/project-image/gesture-controlled_virtual-mouse.png"
import flappybirdgame from "../assets/project-image/flappy_bird_game.png"
import mediadownloadertelegrambot from "../assets/project-image/telegram_bot_media_downloader.png"
import tictactoegame from "../assets/project-image/tic_tac_toe_game.png"
import focusflowweb from "../assets/project-image/focusflow_web.png"
import numberninjaweb from "../assets/project-image/number_ninja_web.png"
import imagebackend from "../assets/project-image/imagebackend.jpg"



const Portfolio = () => {
  const [activeCategory, setActiveCategory] = useState("all");
  const scrollContainerRef = useRef(null);
  const [autoScroll, setAutoScroll] = useState(true);
  const projects = [
    {
      title: "The Travel Delight",
      description:
        "Full-stack travel website built with Next.js, MongoDB, and Tailwind CSS for booking and exploring destinations",
      category: "web development",
      image: thetraveldelight,
      link: "https://thetraveldelight.com",
      clickable: true,
    },
    {
      title: "Tutor Kendra",
      description:
        "React-based platform to find and register tutors, enabling smooth tutor-student connections.",
      category: "web development",
      image: tutorkendra,
      link: "https://tutorkendra.in",
      clickable: true,
    },
        {
      title: "Telegram Bot for Media Downloads",
      description:
        "A Telegram bot that enables users to download media content directly from Instagram and YouTube by simply sending the respective links.",
      category: "backend development",
      image: mediadownloadertelegrambot,
      link: "https://github.com/AnimeshKumarRai/telegram_downloader_bot",
      clickable: true,
    },
    {
      title: "Phishing Detector Web App",
      description:
        "Flask-based app using machine learning to detect and flag phishing websites via URL analysis",
      category: "machine learning",
      image: phishingdetector,
      link: "https://example.com/ai-chat",
      clickable: false,
    },
    {
      title: "AI Chat Web App",
      description:
        "Developed a web application utilizing the OpenAI API to provide users with a seamless interface for interacting with AI in real-time.",
      category: "web development",
      image: aiChat,
      link: "https://example.com/ai-chat",
      clickable: false,
    },
    {
      title: "Recipes Android App",
      description:
        "Built a Flutter-based mobile application that provides users with detailed information about various dietary choices and nutritional content.",
      category: "mobile development",
      image: recipesApp,
      link: "https://example.com/recipes-app",
      clickable: false,
    },
    {
      title: "Weather & Map Web App",
      description:
        "Developed a web application that provides real-time weather updates alongside interactive maps.",
      category: "web development",
      image: weatherMap,
      link: "",
      clickable: false,
    },
    {
      title: "Gesture-Controlled Virtual Mouse",
      description:
        "Developed a computer vision-based virtual mouse that allows users to control cursor movements using hand gestures.",
      category: "computer vision",
      image: gestureMouse,
      link: "",
      clickable: false,
    },
    {
      title: "3D Geological Model Visualization",
      description:
        "ArcGIS data plotting / mapping and visualization and data analysis. Automated through custom scripts and programming",
      category: "computer vision",
      image: model3d,
      link: "",
      clickable: false,
    },
    {
      title: "Flappy Bird Game",
      description:
        "A simple 2D game developed using html, css, and javascript where players navigate a bird through obstacles by clicking to make it fly.",
      category: "game development",
      image: flappybirdgame,
      link: "https://github.com/AnimeshKumarRai/Flappy_Bird",
      clickable: true,
    },
    {
      title: "Tic Tac Toe Game",
      description:
        "A simple Tic Tac Toe game developed using html, css, and javascript where two players can play against computer.",
      category: "game development",
      image: tictactoegame,
      link: "https://github.com/AnimeshKumarRai/Tic_Tac_Toe_Game",
      clickable: true,
    },
    {
      title: "FocusFlow",
      description:
        "A productivity app that helps users manage tasks and stay focused using the Pomodoro technique.",
      category: "web development",
      image: focusflowweb,
      link: "https://animeshkumarrai.github.io/FocusFlow/",
      clickable: true,
    },
    {
      title: "Number Ninja",
      description:
        "A math-based game that challenges players to solve arithmetic problems quickly and accurately.",
      category: "web development",
      image: numberninjaweb,
      link: "https://animeshkumarrai.github.io/FocusFlow/",
      clickable: true,
    },
    {
      title: "Instagram Post Catagorizer",
      description:
        "A backend service that uses machine learning to categorize Instagram posts based on their content.",
      category: "backend development",
      image: imagebackend,
      link: "",
      clickable: false,
    },
    {
      title: "Telegram Resticted Content Downloader",
      description:
        "A javascript code that uses telegram API to download resticted content from telegram channels and groups.",
      category: "backend development",
      image: imagebackend,
      link: "",
      clickable: false,
    },
    {
      title: "Terabox Downloader",
      description:
        "A python script that uses terabox web to download files from terabox.",
      category: "backend development",
      image: imagebackend,
      link: "",
      clickable: false,
    }

  ];

  const categories = [
    "all",
    ...new Set(projects.map((project) => project.category)),
  ];

  const filteredProjects =
    activeCategory === "all"
      ? projects
      : projects.filter((project) => project.category === activeCategory);

  const handleCategoryChange = (category) => {
    setActiveCategory(category);
    setAutoScroll(false); // Stop auto-scroll when user changes category
  };

  // Calculate card width including margin
  // const cardWidth = 256; // w-64 (64 * 4 = 256px) + ml-16 (16 * 4 = 64px) = 320px total
  const totalCardWidth = 320; // w-64 + ml-16

  // Auto-scroll functionality with center alignment
  useEffect(() => {
    if (!autoScroll || !scrollContainerRef.current) return;

    const container = scrollContainerRef.current;
    let currentIndex = 0;

    const interval = setInterval(() => {
      currentIndex = (currentIndex + 1) % filteredProjects.length;
      
      // Calculate scroll position to center the card
      const scrollPosition = currentIndex * totalCardWidth - (container.clientWidth / 2 - totalCardWidth / 2);
      
      container.scrollTo({
        left: scrollPosition,
        behavior: 'smooth'
      });
    }, 3000);

    return () => clearInterval(interval);
  }, [autoScroll, filteredProjects, totalCardWidth]);

  // Manual scroll with center alignment
  const scroll = (direction) => {
    if (!scrollContainerRef.current) return;
    setAutoScroll(false);

    const container = scrollContainerRef.current;
    const currentScroll = container.scrollLeft;
    const containerWidth = container.clientWidth;
    
    // Calculate new scroll position to center the next/previous card
    let newScrollPosition;
    if (direction === 'left') {
      newScrollPosition = currentScroll - totalCardWidth;
    } else {
      newScrollPosition = currentScroll + totalCardWidth;
    }
    
    // Ensure we don't scroll past the boundaries
    newScrollPosition = Math.max(0, Math.min(newScrollPosition, container.scrollWidth - containerWidth));
    
    container.scrollTo({
      left: newScrollPosition,
      behavior: 'smooth'
    });
  };

  // Center the first card on initial render and category change
  useEffect(() => {
    if (!scrollContainerRef.current) return;
    
    const container = scrollContainerRef.current;
    const containerWidth = container.clientWidth;
    const initialScroll = totalCardWidth / 2 - containerWidth / 2;
    
    container.scrollTo({
      left: initialScroll,
      behavior: 'auto'
    });
  }, [filteredProjects, totalCardWidth]);

  return (
    <article className="p-4 max-w-5xl mx-auto" id="portfolio">
      <header>
        <h2 className="text-2xl md:text-3xl font-semibold text-black dark:text-white relative pb-3 mb-6 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-10 after:h-1 after:bg-gradient-to-r after:from-emerald-500 after:to-emerald-300 after:rounded">
          Portfolio
        </h2>
      </header>

      <section className="projects">
        <ul className="filter-list flex flex-wrap gap-4 mb-6">
          {categories.map((category, index) => (
            <li key={index} className="filter-item">
              <button
                onClick={() => handleCategoryChange(category)}
                className={`${
                  activeCategory === category
                    ? "text-emerald-400"
                    : "text-gray-400"
                } hover:text-emerald-300 transition-colors capitalize`}
              >
                {category}
              </button>
            </li>
          ))}
        </ul>

        {/* Mobile - Horizontal Scroll Carousel */}
        <div className="md:hidden relative">
          <HorizontalScrollContainer ref={scrollContainerRef}>
          <div className="flex space-x-4 pb-4 pl-[calc(50%-160px)]"> {/* Center first card */}
            {filteredProjects.map((project, index) => (
              <div 
                key={index} 
                className="flex-shrink-0 w-64 ml-16 snap-center" // Added snap-center
                style={{ scrollSnapAlign: 'center' }}
              >
                  {project.clickable ? (
                    <a
                      href={project.link}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="block border-gray-200 dark:border-gray-500/10 border-2 border-solid rounded-2xl overflow-hidden p-2"
                    >
                      <ProjectCard project={project} />
                    </a>
                  ) : (
                    <div className="block border-gray-200 dark:border-gray-500/10 border-2 border-solid rounded-2xl overflow-hidden p-2">
                      <ProjectCard project={project} />
                    </div>
                  )}
                </div>
              ))}
            </div>
          </HorizontalScrollContainer>
          
          {/* Navigation Arrows */}
          <button 
            onClick={() => scroll('left')} 
            className="absolute left-0 top-1/2 -translate-y-1/2 bg-white dark:bg-gray-800 p-2 rounded-full shadow-md hover:bg-emerald-100 dark:hover:bg-emerald-900 transition-colors z-10"
            aria-label="Scroll left"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-emerald-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <button 
            onClick={() => scroll('right')} 
            className="absolute right-0 top-1/2 -translate-y-1/2 bg-white dark:bg-gray-800 p-2 rounded-full shadow-md hover:bg-emerald-100 dark:hover:bg-emerald-900 transition-colors z-10"
            aria-label="Scroll right"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-emerald-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </button>
        </div>

        {/* Desktop - Grid Layout */}
        <div className="hidden md:block">
          <ul className="project-list grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProjects.map((project, index) => (
              <li key={index} className="project-item group">
                {project.clickable ? (
                  <a
                    href={project.link}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block border-gray-200 dark:border-gray-500/10 border-2 border-solid rounded-2xl overflow-hidden p-2"
                  >
                    <ProjectCard project={project} />
                  </a>
                ) : (
                  <div className="block border-gray-200 dark:border-gray-500/10 border-2 border-solid rounded-2xl overflow-hidden p-2">
                    <ProjectCard project={project} />
                  </div>
                )}
              </li>
            ))}
          </ul>
        </div>
      </section>
    </article>
  );
};

const ProjectCard = ({ project }) => {
  return (
    <div className="h-96">
      <figure className="project-img relative rounded-xl overflow-hidden h-48 mb-4">
        <img
          src={project.image}
          alt={project.title}
          className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-110"
        />
        <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-50 transition-all duration-300 flex items-center justify-center"></div>
      </figure>

      <div className="project-content px-2">
        <h3 className="project-title text-lg font-medium text-black dark:text-white mb-1">
          {project.title}
        </h3>
        <p className="project-category text-sm text-gray-600 dark:text-gray-400 capitalize">
          {project.category}
        </p>
        <p className="project-description text-sm text-gray-500 dark:text-gray-500 mt-2">
          {project.description}
        </p>
      </div>
    </div>
  );
};

const HorizontalScrollContainer = styled.div`
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-snap-type: x mandatory;
  padding-left: calc(50% - 160px); // Center first card

  &::-webkit-scrollbar {
    display: none;
  }

  > div {
    display: flex;
    padding-right: calc(50% - 160px); // Allow last card to center
  }
`;

export default Portfolio;