import {
  // Facebook,
  // Twitter,
  Linkedin,
  Github,
  Instagram,
  Send,
} from "lucide-react";
import ProfilePic from "../assets/myimg.jpg";
import { useEffect, useState, useMemo } from "react";

const Hero = () => {
  const socialLinks = [
    {
      icon: <Github size={18} />,
      label: "GitHub",
      url: "https://github.com/AnimeshKumarRai",
    },
    {
      icon: <Instagram size={18} />,
      label: "Instagram",
      url: "https://instagram.com/animesh__rai",
    },
    {
      icon: <Send size={18} />, // Telegram icon (using Send from lucide-react)
      label: "Telegram",
      url: "https://t.me/animeshrai",
    },
    {
      icon: <Linkedin size={18} />,
      label: "LinkedIn",
      url: "https://linkedin.com/in/animeshkrrai",
    },
    // {
    //   icon: <Twitter size={18} />,
    //   label: "Twitter-X",
    //   url: "https://twitter.com/animesh__rai",
    // },
    // {
    //   icon: <Facebook size={18} />,
    //   label: "Facebook",
    //   url: "https://facebook.com/yourusername",
    // },
  ];

  // Typing animation state
  const roles = useMemo(() => [
    "Software Engineer",
    "Node.js & Express Developer",
    "Tailwind CSS Specialist",
    "Next JS Developer",
    "React JS Developer",
    "Full Stack Developer",
    "WordPress Developer",
    "Database Engineer",
    "UI/UX Enthusiast",
    "JavaScript Expert",
    "MongoDB Specialist",
    "API Architect"
  ], []);
  
  const [currentRoleIndex, setCurrentRoleIndex] = useState(0);
  const [currentRole, setCurrentRole] = useState("");
  const [isDeleting, setIsDeleting] = useState(false);
  const [typingSpeed, setTypingSpeed] = useState(150);

  useEffect(() => {
    const handleType = () => {
      const current = roles[currentRoleIndex];
      if (isDeleting) {
        // If deleting, remove a character
        setCurrentRole(current.substring(0, currentRole.length - 1));
        setTypingSpeed(50); // Faster when deleting
      } else {
        // If typing, add a character
        setCurrentRole(current.substring(0, currentRole.length + 1));
        setTypingSpeed(150); // Normal typing speed
      }

      // If the word is complete, start deleting after a pause
      if (!isDeleting && currentRole === current) {
        setTimeout(() => setIsDeleting(true), 1500);
      } 
      // If deleted completely, move to the next word
      else if (isDeleting && currentRole === "") {
        setIsDeleting(false);
        setCurrentRoleIndex((prevIndex) => (prevIndex + 1) % roles.length);
      }
    };

    const timer = setTimeout(handleType, typingSpeed);
    return () => clearTimeout(timer);
  }, [currentRole, isDeleting, currentRoleIndex, roles, typingSpeed]);

  // Animation effect for shapes
  useEffect(() => {
    const shapes = document.querySelectorAll(".shape");

    const handleMouseMove = (e) => {
      const { clientX, clientY } = e;
      const centerX = window.innerWidth / 2;
      const centerY = window.innerHeight / 2;

      shapes.forEach((shape, index) => {
        // Different movement speeds based on shape index
        const speed = 0.01 + index * 0.005;
        const x = (clientX - centerX) * speed;
        const y = (clientY - centerY) * speed;

        shape.style.transform = `translate(${x}px, ${y}px)`;
      });
    };

    window.addEventListener("mousemove", handleMouseMove);

    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
    };
  }, []);

  return (
    <section
      className="home relative min-h-screen flex items-center justify-center overflow-hidden"
      id="home"
      style={{
        backgroundImage: `ur[](https://i.ibb.co/1G00mfWf/dl-beatsnoop-com-3000-Co-YEX0a9l-I-pica-2.png)`,
      }}
    >
      <div className="intro max-w-[540px] text-center z-10 ">
        {/* Avatar Image - Now circular */}
        <div className="flex justify-center mb-6">
          <img
            src={ProfilePic}
            alt="Profile"
            className="home__img w-[380px] h-[390px] rounded-full object-cover border-4 border-gray-200 dark:border-gray-600 transition-all duration-500 hover:scale-105"
          />
        </div>

        {/* Name */}
        <h1 className="home__name  font-bold mb-2 dark:text-white text-gray-900">
          <span className="text-gray-400 dark:text-gray-400 text-base md:text-lg"> Hi, I'm </span><span className="text-emerald-700 dark:text-emerald-400 text-2xl md:text-4xl"> Animesh Kumar Rai </span>
        </h1>

        {/* Title with typing animation */}
        <div className="home__education flex justify-center items-center mb-6">
          <span className="text-lg dark:text-gray-300 text-gray-600">
            {currentRole}
            <span className="ml-1 inline-block w-1 h-6 bg-gray-600 dark:bg-gray-300 animate-blink"></span>
          </span>
        </div>

        {/* Social Links */}
        <ul className="home__socials flex justify-center gap-7 my-6">
          {socialLinks.map((social, index) => (
            <li key={index} className="relative group">
              <a
                href={social.url}
                target="_blank"
                rel="noopener noreferrer"
                className="home__social-link text-gray-500 dark:text-gray-400 hover:text-emerald-400 dark:hover:text-emerald-400 transition-colors duration-300"
              >
                {social.icon}
                {/* <span className="absolute top-1/2 left-full transform -translate-y-1/2 ml-3 bg-raw-seinna text-white text-sm font-bold px-2 py-1 rounded opacity-0 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-300 translate-x-2">
                  {social.label}
                </span> */}
              </a>
            </li>
          ))}
        </ul>

        {/* Contact Button */}
        <a
          href="#contact"
          className="btn inline-block bg-transparent border-2 border-gray-900 dark:border-white text-gray-900 dark:text-white font-bold uppercase tracking-wider px-6 py-3 rounded mt-4 hover:bg-gray-900 hover:text-white dark:hover:bg-white dark:hover:text-gray-900 transition-colors duration-300 hover:scale-105 transform"
        >
          Contact Me
        </a>

        {/* Scroll Down */}
        <div className="scroll__down absolute bottom-10 left-0 w-full">
          <a
            href="#about"
            className="mouse__wrapper flex flex-col items-center"
          >
            <span className="home__scroll-name text-sm mb-2 dark:text-white text-gray-900">
              Scroll Down
            </span>
            <span className="mouse block border-2 border-gray-500 dark:border-gray-400 h-6 w-5 rounded-xl relative mx-auto">
              <span className="wheel absolute top-1 left-1/2 transform -translate-x-1/2 bg-gray-900 dark:bg-white w-1 h-1 rounded-full animate-bounce"></span>
            </span>
          </a>
        </div>
      </div>

      {/* Animated Shapes */}
      <div className="shapes absolute left-0 top-0 h-full w-full pointer-events-none">
        {/* Shape 1 - Floating animation */}
        <svg
          width="27"
          height="29"
          className="shape s1 absolute left-[2%] top-[10%] animate-float-1"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M21.15625.60099c4.37954 3.67487 6.46544 9.40612 5.47254 15.03526-.9929 5.62915-4.91339 10.30141-10.2846 12.25672-5.37122 1.9553-11.3776.89631-15.75715-2.77856l2.05692-2.45134c3.50315 2.93948 8.3087 3.78663 12.60572 2.22284 4.297-1.5638 7.43381-5.30209 8.22768-9.80537.79387-4.50328-.8749-9.08872-4.37803-12.02821L21.15625.60099z"
            fill="#FFD15C"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 2 - Floating animation with delay */}
        <svg
          width="26"
          height="26"
          className="shape s2 absolute left-[18%] top-[30%] animate-float-2"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M13 3.3541L2.42705 24.5h21.1459L13 3.3541z"
            stroke="#FF4C60"
            strokeWidth="3"
            fill="none"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 3 - Rotating animation */}
        <svg
          width="30"
          height="25"
          className="shape s3 absolute left-[5%] bottom-[30%] animate-spin-slow"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M.1436 8.9282C3.00213 3.97706 8.2841.92763 14.00013.92796c5.71605.00032 10.9981 3.04992 13.85641 8 2.8583 4.95007 2.8584 11.0491-.00014 16.00024l-2.77128-1.6c2.28651-3.96036 2.28631-8.84002.00011-12.8002-2.2862-3.96017-6.5124-6.40017-11.08513-6.4-4.57271.00018-8.79872 2.43984-11.08524 6.4002l-2.77128-1.6z"
            fill="#44D7B6"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 4 - Pulsing animation */}
        <svg
          width="15"
          height="23"
          className="shape s4 absolute left-[2%] bottom-[10%] animate-pulse"
          xmlns="http://www.w3.org/2000/svg"
        >
          <rect
            transform="rotate(30 9.86603 10.13397)"
            x="7"
            width="3"
            height="25"
            rx="1.5"
            fill="#FFD15C"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 5 - Floating animation */}
        <svg
          width="15"
          height="23"
          className="shape s5 absolute left-[44%] top-[10%] animate-float-3"
          xmlns="http://www.w3.org/2000/svg"
        >
          <rect
            transform="rotate(30 9.86603 10.13397)"
            x="7"
            width="3"
            height="25"
            rx="1.5"
            fill="#6C6CE5"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 6 - Bouncing animation */}
        <svg
          width="49"
          height="17"
          className="shape s6 absolute left-[36%] bottom-[10%] animate-bounce-slow"
          xmlns="http://www.w3.org/2000/svg"
        >
          <g fill="#FF4C60" fillRule="evenodd">
            <path d="M.5 16.5c0-5.71709 2.3825-10.99895 6.25-13.8567 3.8675-2.85774 8.6325-2.85774 12.5 0C23.1175 5.50106 25.5 10.78292 25.5 16.5H23c0-4.57303-1.90625-8.79884-5-11.08535-3.09375-2.28652-6.90625-2.28652-10 0C4.90625 7.70116 3 11.92697 3 16.5H.5z" />
            <path d="M23.5 16.5c0-5.71709 2.3825-10.99895 6.25-13.8567 3.8675-2.85774 8.6325-2.85774 12.5 0C46.1175 5.50106 48.5 10.78292 48.5 16.5H46c0-4.57303-1.90625-8.79884-5-11.08535-3.09375-2.28652-6.90625-2.28652-10 0-3.09375 2.28651-5 6.51232-5 11.08535h-2.5z" />
          </g>
        </svg>

        {/* Shape 7 - Floating animation with delay */}
        <svg
          width="26"
          height="26"
          className="shape s7 absolute top-[20%] right-[25%] animate-float-4"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M13 22.6459L2.42705 1.5h21.1459L13 22.6459z"
            stroke="#FFD15C"
            strokeWidth="3"
            fill="none"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 8 - Rotating animation */}
        <svg
          width="19"
          height="21"
          className="shape s8 absolute right-[24%] bottom-[20%] animate-spin-slow"
          xmlns="http://www.w3.org/2000/svg"
        >
          <rect
            transform="rotate(-40 6.25252 10.12626)"
            x="7"
            width="3"
            height="25"
            rx="1.5"
            fill="#6C6CE5"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 9 - Floating animation */}
        <svg
          width="30"
          height="25"
          className="shape s9 absolute right-[2%] top-[10%] animate-float-5"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M29.8564 16.0718c-2.85854 4.95114-8.1405 8.00057-13.85654 8.00024-5.71605-.00032-10.9981-3.04992-13.85641-8-2.8583-4.95007-2.8584-11.0491.00014-16.00024l2.77128 1.6c-2.28651 3.96036-2.28631 8.84002-.00011 12.8002 2.2862 3.96017 6.5124 6.40017 11.08513 6.4 4.57271-.00018 8.79872-2.43984 11.08524-6.4002l2.77128 1.6z"
            fill="#6C6CE5"
            fillRule="evenodd"
          />
        </svg>

        {/* Shape 10 - Pulsing animation */}
        <svg
          width="47"
          height="29"
          className="shape s10 absolute top-[45%] right-[11%] animate-pulse-slow"
          xmlns="http://www.w3.org/2000/svg"
        >
          <g fill="#44D7B6" fillRule="evenodd">
            <path d="M46.78878 17.19094c-1.95535 5.3723-6.00068 9.52077-10.61234 10.8834-4.61167 1.36265-9.0893-.26708-11.74616-4.27524-2.65686-4.00817-3.08917-9.78636-1.13381-15.15866l2.34923.85505c-1.56407 4.29724-1.2181 8.92018.90705 12.12693 2.12514 3.20674 5.70772 4.5107 9.39692 3.4202 3.68921-1.0905 6.92581-4.40949 8.48988-8.70673l2.34923.85505z" />
            <path d="M25.17585 9.32448c-1.95535 5.3723-6.00068 9.52077-10.61234 10.8834-4.61167 1.36264-9.0893-.26708-11.74616-4.27525C.16049 11.92447-.27182 6.14628 1.68354.77398l2.34923.85505c-1.56407 4.29724-1.2181 8.92018.90705 12.12692 2.12514 3.20675 5.70772 4.5107 9.39692 3.4202 3.68921-1.0905 6.92581-4.40948 8.48988-8.70672l2.34923.85505z" />
          </g>
        </svg>

        {/* Shape 11 - Floating animation with delay */}
        <svg
          width="33"
          height="20"
          className="shape s11 absolute bottom-[10%] right-[2%] animate-float-6"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M32.36774.34317c.99276 5.63023-1.09332 11.3614-5.47227 15.03536-4.37895 3.67396-10.3855 4.73307-15.75693 2.77837C5.76711 16.2022 1.84665 11.53014.8539 5.8999l3.15139-.55567c.7941 4.50356 3.93083 8.24147 8.22772 9.8056 4.29688 1.56413 9.10275.71673 12.60554-2.2227C28.34133 9.98771 30.01045 5.4024 29.21635.89884l3.15139-.55567z"
            fill="#FFD15C"
            fillRule="evenodd"
          />
        </svg>
      </div>

      {/* Add these styles to your global CSS or in a style tag */}
      <style jsx>{`
        @keyframes float {
          0%,
          100% {
            transform: translateY(0);
          }
          50% {
            transform: translateY(-30px);
          }
        }
        @keyframes float-2 {
          0%,
          100% {
            transform: translateY(0);
          }
          50% {
            transform: translateY(-15px) translateX(20px);
          }
        }
        @keyframes float-3 {
          0%,
          100% {
            transform: translateY(0) translateX(0);
          }
          50% {
            transform: translateY(-10px) translateX(10px);
          }
        }
        @keyframes float-4 {
          0%,
          100% {
            transform: translateY(0) translateX(0);
          }
          50% {
            transform: translateY(-15px) translateX(15px);
          }
        }
        @keyframes float-5 {
          0%,
          100% {
            transform: translateY(0);
          }
          50% {
            transform: translateY(30px);
          }
        }
        @keyframes float-6 {
          0%,
          100% {
            transform: translateY(0) translateX(0);
          }
          50% {
            transform: translateY(-25px) translateX(-15px);
          }
        }
        @keyframes spin-slow {
          0% {
            transform: rotate(0deg);
          }
          100% {
            transform: rotate(360deg);
          }
        }
        @keyframes pulse {
          0%,
          100% {
            opacity: 1;
          }
          50% {
            opacity: 0.2;
          }
        }
        @keyframes pulse-slow {
          0%,
          100% {
            transform: scale(1);
          }
          50% {
            transform: scale(1.2);
          }
        }
        @keyframes bounce-slow {
          0%,
          100% {
            transform: translateY(0);
          }
          50% {
            transform: translateY(-20px);
          }
        }
        @keyframes blink {
          0%,
          100% {
            opacity: 1;
          }
          50% {
            opacity: 0;
          }
        }
        .animate-float-1 {
          animation: float 6s ease-in-out infinite;
        }
        .animate-float-2 {
          animation: float-2 7s ease-in-out infinite;
        }
        .animate-float-3 {
          animation: float-3 8s ease-in-out infinite;
        }
        .animate-float-4 {
          animation: float-4 9s ease-in-out infinite;
        }
        .animate-float-5 {
          animation: float-5 10s ease-in-out infinite;
        }
        .animate-float-6 {
          animation: float-6 11s ease-in-out infinite;
        }
        .animate-spin-slow {
          animation: spin-slow 20s linear infinite;
        }
        .animate-pulse {
          animation: pulse 3s ease-in-out infinite;
        }
        .animate-pulse-slow {
          animation: pulse-slow 5s ease-in-out infinite;
        }
        .animate-bounce-slow {
          animation: bounce-slow 4s ease-in-out infinite;
        }
        .animate-blink {
          animation: blink 1s infinite;
        }
      `}</style>
    </section>
  );
};

export default Hero;