import { useState, useEffect } from "react";
import Switch from "./theme_button";
import Logo_White from "../assets/logo_white.svg";
import Logo_Black from "../assets/logo_black.svg";

const Navbar = ({ activeSection }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  useEffect(() => {
    const savedTheme = localStorage.getItem("theme");
    if (savedTheme === "light-theme") {
      setIsDarkMode(false);
      document.documentElement.classList.remove("dark");
    } else {
      setIsDarkMode(true);
      document.documentElement.classList.add("dark");
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add("dark");
      localStorage.setItem("theme", "dark-theme");
    } else {
      document.documentElement.classList.remove("dark");
      localStorage.setItem("theme", "light-theme");
    }
  }, [isDarkMode]);

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode);
  };

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
    document.body.classList.toggle("overflow-hidden");
  };

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      window.scrollTo({
        top: element.offsetTop,
        behavior: 'smooth'
      });
    }
  };

  const navLinks = [
    { id: "home", label: "Home" },
    { id: "about", label: "About" },
    { id: "skills", label: "Skills" },
    { id: "resume", label: "Resume" },
    { id: "portfolio", label: "Portfolio" },
    { id: "contact", label: "Contact" },
  ];

  return (
    <header className="fixed top-0 left-0 w-full pb-4 transition-all duration-300 z-50">
      <div className="bg-gradient-to-b from-white dark:from-black to-transparent pt-4 pb-6">
        <div className="container mx-auto px-4 flex justify-between items-center">
          <h1 className="text-2xl font-saira-stencil dark:text-white text-gray-900">
            <a href="#home" className="flex items-center">
              <img src={Logo_Black} alt="Logo" className="h-8 mr-2 dark:hidden" />
              <img src={Logo_White} alt="Logo" className="h-8 mr-2 hidden dark:block" />
              Animesh<span className="text-emerald-500">.</span>Rai
            </a>
          </h1>

          <nav className="hidden lg:flex items-center gap-8">
            {navLinks.map((link) => (
              <a
                key={link.id}
                href={`#${link.id}`}
                onClick={(e) => {
                  e.preventDefault();
                  scrollToSection(link.id);
                }}
                className={`relative font-poppins dark:text-white text-gray-900 py-2 transition-colors duration-300 ${
                  activeSection === link.id
                    ? "text-emerald-500"
                    : "hover:text-emerald-500"
                }`}
              >
                {link.label}
                {activeSection === link.id && (
                  <span className="absolute bottom-0 left-0 w-full h-0.5 bg-emerald-500"></span>
                )}
              </a>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            {/* Modified Switch component integration */}
            <label className="cursor-pointer">
              <Switch isChecked={isDarkMode} onChange={toggleTheme} />
            </label>

            <button
              onClick={toggleMenu}
              className={`lg:hidden relative z-50 transition-transform duration-300 ${
                isMenuOpen ? "-rotate-45" : "-rotate-55"
              }`}
              aria-label="Toggle Menu"
              title="Toggle Menu"
            >
              <span
                className={`block w-5 h-0.5 dark:bg-white bg-gray-900 my-1 transition-all duration-300 ${
                  isMenuOpen ? "w-2 rotate-90 -translate-x-1" : "ml-auto"
                }`}
              />
              <span className="block w-5 h-0.5 dark:bg-white bg-gray-900 my-1" />
              <span
                className={`block w-5 h-0.5 dark:bg-white bg-gray-900 my-1 transition-all duration-300 ${
                  isMenuOpen ? "w-2 rotate-90 translate-x-1" : "mr-auto"
                }`}
              />
            </button>
          </div>

          <nav
            className={`lg:hidden fixed top-0 left-0 w-full h-full flex items-center justify-center transition-all duration-700 ease-[cubic-bezier(0.71,0.01,0.24,0.99)] dark:bg-gray-800 bg-white z-40 ${
              isMenuOpen
                ? "translate-y-0 opacity-100 visible delay-0"
                : "translate-y-full opacity-0 invisible delay-500"
            }`}
          >
            <ul className="text-center">
              {navLinks.map((link) => (
                <li key={link.id} className="my-5 overflow-hidden">
                  <a
                    href={`#${link.id}`}
                    onClick={(e) => {
                      e.preventDefault();
                      scrollToSection(link.id);
                      setIsMenuOpen(false);
                      document.body.classList.remove("overflow-hidden");
                    }}
                    className={`relative text-2xl font-poppins dark:text-white text-gray-900 py-2 mx-auto transition-transform duration-700 ease-[cubic-bezier(0.68,-0.55,0.27,2)] ${
                      isMenuOpen ? "translate-y-0" : "translate-y-12"
                    } ${activeSection === link.id ? "text-emerald-500" : ""}`}
                  >
                    {link.label}
                    {activeSection === link.id && (
                      <span className="absolute bottom-0 left-0 w-full h-0.5 bg-emerald-500"></span>
                    )}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
        </div>
      </div>
    </header>
  );
};

export default Navbar;